import { z } from "zod";

// A display-only section generated by a provider (not the manual ledger's user `memo`).
// Account-level `Note[]` (e.g. BTC unconfirmed/derived addresses) or one balance-level `Note`
// (e.g. a CEX coin's locked amount). Values stay structured; the frontend formats them.
export const NoteIcon = z.enum(["info", "success", "warning", "error", "help"]);

export const NoteRow = z.object({
  label: z.string(),
  value: z.union([z.string(), z.number()]).optional(),
  unit: z.string().optional(),
  href: z.string().optional(),
});

export const Note = z.object({
  title: z.string(),
  icon: NoteIcon.optional(),
  content: z.union([z.string(), z.array(NoteRow)]),
  // Not rendered; only used by the account drawer to group notes into per-wallet tabs.
  group: z.string().optional(),
});

export type NoteIcon = z.infer<typeof NoteIcon>;
export type NoteRow = z.infer<typeof NoteRow>;
export type Note = z.infer<typeof Note>;
